"صلاحيات كل موظف تُعدَّل من «🔐 جدول الصلاحيات» في القائمة.":"Each employee's permissions are edited in “🔐 Permissions table” in the menu.",
"ضع العلامة لمنح الصلاحية وأزلها لسحبها، وتُحفظ فوراً. تصل الموظف عند فتحه المنصة أو خلال لحظات إن كانت مفتوحة.":"Tick to grant a permission and untick to remove it; it saves immediately. It reaches the employee when they open the platform, or within moments if it is open.",
"🔑 يمكنك تعديل الطلبات والعهدة والسيارات والهدايا للمحاسبين. باقي الصلاحيات للأدمن ومالك النظام.":"🔑 You can edit Orders, Custody, Vehicles and Gifts for accountants. Other permissions are for the admin and the system owner.",
"للمشاهدة. التعديل للأدمن ومالك النظام.":"View only. Editing is for the admin and the system owner.",
