"«مراسلة الفروع»: يرى الفروع في الدردشة ويراسلها، ويظهر لها في قسم المستودع. «الدردشة مفتوحة»: إزالتها تقفل الدردشة كلها عن الموظف.":"“Message branches”: sees branches in chat and messages them, and appears to them in the Warehouse section. “Chat open”: unticking it locks chat entirely for the employee.",
"لا يوجد موظفون بعد. أضفهم من «👥 الموظفون والحسابات».":"No staff yet. Add them from “👥 Staff and accounts”.",
