"الأقسام الخاصة":"Private sections",
"قفل الأقسام وفتحها لمالك النظام فقط.":"Only the system owner can lock and unlock sections.",
"قفل الأقسام وفتحها لمالك النظام فقط":"Only the system owner can lock and unlock sections",
