"أنت مستثنى من القفل وتراه كما كان.":"You are exempt from the lock and see it as before.",
"لا يظهر لك ولا لباقي المديرين ولا للمتابع، ولا يدخل في النسخة الاحتياطية التي تأخذها. النسخة الكاملة عند مالك النظام.":"It is hidden from you, the other managers and the viewer, and it is not included in the backup you take. The full backup is with the system owner.",
"القسم ظاهر للمديرين والمتابع كالمعتاد.":"The section is visible to managers and the viewer as usual.",
"لا يوجد مالك نظام الآن. عيّنه من «👥 الموظفون والحسابات» ليستطيع قفل الأقسام.":"There is no system owner now. Appoint one from “👥 Staff & accounts” so he can lock sections.",
"القسم الخاص لا يراه ولا يعدّل فيه إلا أنت ومن تحددهم هنا. يختفي عن الأدمن وباقي المديرين والمتابع، والقفل والفتح لك وحدك.":"A private section is seen and edited only by you and those you choose here. It disappears for the admin, the other managers and the viewer, and only you lock or unlock it.",
"من يرى القسم الآن":"Who can see the section now",
"استثناء من القفل":"Exempt from the lock",
"لا أحد":"Nobody",
"مستثنى":"Exempt",
"له «أوامر الشراء»":"has “Purchase orders”",
"له «استلام الحاويات»":"has “Receive containers”",
"المستثنى يرى القسم كما كان قبل القفل بحسب دوره. صلاحيتا «أوامر الشراء» و«استلام الحاويات» في «🔐 جدول الصلاحيات» تعدّلهما أنت فقط ما دام القسم مقفولاً، وكذلك كلمات مرور أصحابهما.":"An exempt person sees the section as before the lock, according to his role. While the section is locked, only you can change “Purchase orders” and “Receive containers” in the “🔐 Permissions table”, and the passwords of those who hold them.",
"النسخة الاحتياطية التي يأخذها غيرك لا تشمل هذا القسم وهو مقفول، فخذ نسختك من زر «📥 نسخة». كل قفل وفتح يُسجَّل في «📜 السجل».":"A backup taken by anyone else does not include this section while it is locked, so take your own from the “📥 Backup” button. Every lock and unlock is recorded in “📜 Log”.",
"القسم ظاهر الآن للأدمن والمديرين والمتابع. بعد القفل يبقى لك ولمن له «أوامر الشراء» أو «استلام الحاويات» ولمن تستثنيه.":"The section is now visible to the admin, managers and the viewer. After locking it stays for you, for those who hold “Purchase orders” or “Receive containers”, and for those you exempt.",
"قسم أوامر الشراء خاص الآن: هذه الصلاحية يمنحها مالك النظام فقط":"The purchase orders section is private now: only the system owner grants this permission",
"قسم خاص: يعدّلها مالك النظام فقط":"Private section: only the system owner changes it",
"🔓 فُتح القسم":"🔓 Section unlocked",
"🔒 أصبح القسم خاصاً":"🔒 The section is now private",
"أصبح مستثنى ويرى القسم":"Now exempt and can see the section",
"أُزيل الاستثناء":"Exemption removed",
"فتح قسم أوامر الشراء؟":"Unlock the purchase orders section?",
"سيراه الأدمن وباقي المديرين والمتابع كما كان.":"The admin, the other managers and the viewer will see it as before.",
"قفل قسم أوامر الشراء؟":"Lock the purchase orders section?",
"سيختفي عن الأدمن وباقي المديرين والمتابع ولن يستطيعوا التعديل فيه. يبقى لك ولمن له «أوامر الشراء» أو «استلام الحاويات».":"It will disappear for the admin, the other managers and the viewer, and they will not be able to edit it. It stays for you and for those who hold “Purchase orders” or “Receive containers”.",
"تذكّر: خذ نسختك الاحتياطية بنفسك، فنسخة غيرك لن تشمل هذا القسم.":"Remember: take your own backup, because anyone else’s backup will not include this section.",
"إشعارات وصول الحاويات مستمرة والقسم مقفول ليستعد المستودع: تصل المديرين والمحاسبين، وتعرف الفروع عند وصول الحاوية المستودع، وفيها وصف البضاعة وعدد الحاويات فقط. ويصل الأدمن ومن يستلم الحاويات اسم المورد ورقم الأمر أيضاً. لا أسعار ولا مرفقات في أي إشعار.":"Container arrival notifications continue while the section is locked so the warehouse can prepare: they reach managers and accountants, and branches are told when a container reaches the warehouse, with the goods description and number of containers only. The admin and those who receive containers also get the supplier name and order number. No prices or attachments in any notification.",
"إشعارات وصول الحاويات تصلك كالمعتاد لتجهيز المستودع.":"Container arrival notifications still reach you as usual so the warehouse can prepare.",
"اضغط العين لتخفي القسم عن الشخص أو تظهره له، والجرس لتوقف إشعاراته عنه أو تشغّلها. يُحفظ فوراً، والتعديل هنا لك وحدك.":"Tap the eye to hide the section from a person or show it, and the bell to stop or resume its notifications for him. Saved instantly, and only you can change this.",
"للعرض فقط. الإخفاء والإظهار والإشعارات يحددها مالك النظام.":"View only. Hiding, showing and notifications are set by the system owner.",
