"«خاص» يحجب القسم عن كل من ليس له صلاحيته صراحةً (الأدمن والمديرون والمتابع)، حتى من يُضاف لاحقاً، ثم تُظهره لمن تريد من الجدول. والإخفاء بالاسم يغلب أي صلاحية.":"“Private” hides the section from everyone without an explicit permission for it (the admin, managers and the viewer), including people added later; then you show it to whoever you want from the table. Hiding by name overrides any permission.",
"الإخفاء لا يوقف الإشعارات: أطفئ الجرس لمن لا تريد أن تصله. لا أسعار ولا مرفقات في أي إشعار.":"Hiding does not stop notifications: turn the bell off for whoever should not get them. No prices or attachments in any notification.",
"القسم المحجوب عن شخص لا يدخل نسخته الاحتياطية، فخذ نسختك من زر «📥 نسخة». كل تغيير هنا يُسجَّل في «📜 السجل».":"A section hidden from someone is left out of his backup, so take your own from the “📥 Backup” button. Every change here is recorded in “📜 Log”.",
"لا يدخل في النسخة الاحتياطية التي تأخذها. النسخة الكاملة عند مالك النظام.":"is not included in the backup you take. The full backup is with the system owner.",
